quests[8192] = { id = 8192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animist's Caress", progress = "Zanza can create the ancient troll enchantments with the right components.\n\nThe first is a primal Hakkari idol that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.\n\nThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed hoodoo piles.\n\nBring me these things and I will create a powerful enchantment for you!", completion = "Use it well, {class}. Show the Hakkari no mercy!" }
quests[8193] = { id = 8193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Prize", progress = "Today between 2pm and 4pm we have a contest to determine who the greatest angler of them all is!   Just be the FIRST PERSON to bring me 40 Tastyfish fished from the Tastyfish schools found along the coast of Stranglethorn before anyone else does and you will be declared the Master Angler! \n\n If you are not the first person to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish you bring her.\n\n Oh, and don't delay, Tastyfish go bad quickly!", completion = "Hurry up and turn those in if you want to be declared the Master Angler!  I have been standing around here for HOURS with nothing to eat!   Hand those suckers over!" }
quests[8194] = { id = 8194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apprentice Angler", progress = "Even though we already have a contest winner, I will still buy your Tastyfish from you at a reasonable price.   Whadda ya say!", completion = "This deal works for me if it works for you!" }
quests[8195] = { id = 8195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zulian, Razzashi, and Hakkari Coins", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.", completion = "Excellent - this set of coins will make a fine addition to our growing collection... one that we will use in the tribe's defense against the rise of the Blood God.  You've earned this Honor Token, {name}, as well as the thanks of the tribe!" }
quests[8196] = { id = 8196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence Mangoes", progress = "The extremely potent essence mango grows across many of the islands in the South Seas.  A single mango will refresh those who eat it, both physically and mentally.  If you've never had one, you do yourself a disservice!\n\nWe have enough of a supply here on the isle to offer you a handful in exchange for a Zandalar Honor Token.  Speak with Vinchaxa if you need to learn how to get tokens; otherwise, let's get to the business at hand!", completion = "A fair trade, my friend - please enjoy the luscious fruits of the South Seas, with the tribe's blessing." }
quests[8201] = { id = 8201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Collection of Heads", description = "It is true.  Hakkar now dwells in Zul'Gurub, bathing in the power of our gods.  Enthralled high priests now channel the energies of our most sacred divinities into the Soulflayer, who will soon have a strength beyond any being of Azeroth.  He must be stopped!\n\nTake this sacred cord, and string through it the heads of the high priests responsible for channeling our gods' energy.\n\nWhen you have done this, return to me.", progress = "Do you have the collection of heads, {name}?  We must stop Hakkar from gaining more power!", completion = "You gained the heads!  You have halted the plundering of our gods' power, and weakened Hakkar!\n\nYour actions are truly heroic, {name}.  May the heads of these troll thralls plead to you for mercy long after their blood chills.", objectives = "String 5 Channeler's Heads, then return the Collection of Troll Heads to Exzhal on Yojamba Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8221] = { id = 8221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Fish - Keefer's Angelfish", progress = "*Whir* *Click*\n\n  I seek rare fish for Fishmaster Bluegill to catalogue.   If you bring me a Keefer's Angelfish, I will provide you with this fine reward. \n\n *Zzzap* *Whir*", completion = "*Whir* \n\n Identification of Keefer's Angelfish complete. \n\n Your Reward is now available. \n\n *click-click* *Bzzzz*" }
quests[8222] = { id = 8222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glowing Scorpid Blood", progress = "In all my time working the Faire, I've learned a lot of things about customers.  Here's one of those nuggets of wisdom: customers love stuff that glows!  It doesn't matter what it is - you could take a broken chair leg and make it glow, and every child will come from miles around to get one!\n\nSo, {name}, I need glowing scorpid blood.  You can find it from the scorpids of Sillithus, or the Blasted Lands, or the Burning Steppes.", completion = "Great job, {name}!  Thanks a lot!  I'm going to make paint from this blood and turn all kinds of cheap junk into glowing treasure!\n\nHere are your tickets, and thanks again!" }
quests[8223] = { id = 8223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Glowing Scorpid Blood", progress = "That scorpid blood is working out great, {name}!  It's amazing how a little sparkle and shine can create a prized bauble out of an otherwise piece of junk.  The patrons love the stuff, and love is what it's all about, don't you think...\n\nYou've been a big help to me, {name}, and although I don't have a great need for more glowing scorpid blood, if you bring me more then I'll still trade you some tickets.", completion = "Thanks again, {name}.  Here are your tickets!" }
quests[8224] = { id = 8224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Fish - Dezian Queenfish", progress = "*Whir* *Click*\n\n  I seek rare fish for Fishmaster Bluegill to catalogue.   If you bring me a Dezian Queenfish, I will provide you with this fine reward. \n\n *Zzzap* *Whir*", completion = "*Whir* \n\n Identification of Dezian Queenfish complete. \n\n Your Reward is now available. \n\n *click-click* *Bzzzz*" }
quests[8225] = { id = 8225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Fish - Brownell's Blue Striped Racer", progress = "*Whir* *Click*\n\n  I seek rare fish for Fishmaster Bluegill to catalogue.   If you bring me a Brownell's Blue Striped Racer, I will provide you with this fine reward. \n\n *Zzzap* *Whir*", completion = "*Whir* \n\n Identification of Brownell's Racer complete. \n\n Your Reward is now available. \n\n *click-click* *Bzzzz*" }
quests[8226] = { id = 8226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Fish - Pale Ghoulfish" }
quests[8227] = { id = 8227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat's Measuring Tape", description = "Amongst the shattered fishing lures and tackle is a rolled, silken measuring tape.  Attached to the tape is a label that reads:\n\n\"Nat Pagle, Dustwallow Marsh.\"", progress = "Hello there, sonny.  You here to do some fishing?", completion = "Why, you found my favorite measuring tape!  I love this tape!  I measured some of the biggest fish I ever caught with it...\n\nBut, I lost this tape in Zul'Gurub... you've been to Zul'Gurub?  Did you see the fabled Gahz'ranka?\n\nWell... do you want to catch him?", objectives = "Return Nat's Measuring Tape to Nat Pagle in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8228] = { id = 8228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Could I get a Fishing Flier?", progress = "There is a Fishing Contest in Booty Bay this Sunday! Here are the rules of the tournament if you want to participate!", completion = "There is a Fishing Contest in Booty Bay this Sunday!   Here are the rules of the tournament if you want to participate!" }
quests[8229] = { id = 8229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Could I get a Fishing Flier?", progress = "There is a Fishing Contest in Booty Bay this Sunday! Here are the rules of the tournament if you want to participate!", completion = "There be a Fishin Contest in Booty Bay this Sunday!   Here are the rules for ya!" }
quests[8231] = { id = 8231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wavethrashing", description = "The wavethrasher is an amphibious beast living only here in Azshara.  They are powerful and resilient.\n\nThe tough, reflective scales from a wavethrasher mirror the strength of the hunter.\n\nTrack and hunt wavethrashers along the coast of Azshara, and bring me their scales.", objectives = "Bring 6 Wavethrasher Scales to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8232] = { id = 8232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Green Drake", description = "Now I set you on a dangerous hunt to slay the green drake, Morphaz, and bring his tooth to me.  Morphaz dwells deep in Temple of Atal'Hakkar, the entrance to which lies in Swamp of Sorrows.\n\nIf you wish to defeat him, you must not go alone.  This drake is an enemy of many -- seek others who wish to destroy him.\n\nThe drake's tooth represents the power a hunter will find in the company of others.  Bring it to me and you will have learned much.You will be able to choose one of these rewards:", objectives = "Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8233] = { id = 8233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Simple Request", description = "Lord Jorach Ravenholdt has requested your presence.  The matter is secret, and I cannot say any more.\n\nRavenholdt Manor is located in the Hillsbrad Foothills -- look for a path in the mountains northwest of Durnhold Keep.", objectives = "Speak with Lord Jorach Ravenholdt in Ravenholdt Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8234] = { id = 8234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealed Azure Bag", description = "First things first.  What I've lost is a small blue bag, the contents of which are a private matter.\n\nDon't bother going after the thieves, because they are already dead.  What we do know is the fools couldn't get the bag open. so they sold it to some timbermaw shaman in Azshara as a holy relic.  Clever.\n\nI need you to travel to Azshara and retrieve it from the shaman through subtlety... or force.  Better luck with the first method, I'd wager.  Once acquired, take it to Archmage Xylem.", objectives = "Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara. Then take the bag to Archmage Xylem, also found in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8235] = { id = 8235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encoded Fragments", description = "Lord Ravenholdt has asked a favor of us both.  He wishes to remove the enchantment from this bag.\n\nUnfortunately, some of my books on the subject of dispelling were taken recently, only to be destroyed by savages.  The remains of my books are still valuable to me.\n\nIf you can bring me enough of the encoded fragments, I can piece them back together.  Your best chance is to kill the beasts of Azshara, since they have a tendency to pick up just about anything.", objectives = "Bring 10 Encoded Fragments to Archmage Xylem in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8236] = { id = 8236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azure Key", description = "It will take some time to decipher the fragments and remove the enchantment.  When I am complete, I'll deliver the bag to Lord Ravenholdt personally.\n\nThere is still the matter of the key, said to be held by a green drake known as Morphaz.  The drake has made its home deep in the Temple of Atal'Hakkar, the entrance to which lies in the Swamp of Sorrows.\n\nGather your friends and venture to his lair.  Lord Ravenholdt will await your return with the key.", objectives = "Return the Azure Key to Lord Jorach Ravenholdt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8237] = { id = 8237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Blink of an Eye Tracking Quest" }
quests[8238] = { id = 8238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashi, Vilebranch, and Witherbark Coins", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.", completion = "Excellent - this set of coins will make a fine addition to our growing collection... one that we will use in the tribe's defense against the rise of the Blood God.  You've earned this Honor Token, {name}, as well as the thanks of the tribe!" }
quests[8239] = { id = 8239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandfury, Skullsplitter, and Bloodscalp Coins", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you one of our Honor Tokens for a set of three.  You may use the Tokens with Rin'wosho the Trader; he offers our heroes special items for them.", completion = "Excellent - this set of coins will make a fine addition to our growing collection... one that we will use in the tribe's defense against the rise of the Blood God.  You've earned this Honor Token, {name}, as well as the thanks of the tribe!" }
quests[8240] = { id = 8240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bijou for Zanza", description = "The destruction of the various Hakkari Bijous is of grave importance to us, so much so that we welcome outsiders of the tribe to do so for themselves!\n\nTake any one of the bijous that you find in Zul'Gurub to the Altar of Zanza and destroy it.  For this one time alone, I will give you an additional Honor Token from our tribe; this is above and beyond what you would normally receive.\n\nWitness for yourself the blessings of Zanza!", completion = "Excellent... each bijou we wrest away from the Blood God's minions is one step closer we all are to finally defeating them once and for all.  You bring honor to the Zandalar - and yourself - through your noble actions.\n\nRemember {name}, you may always destroy the bijous you find in Zul'Gurub at the altar.  For each one, you will gain recognition and an Honor Token!  Just remember to have an open space in your inventory if you don't have one of the tokens already.", objectives = "Destroy any one of the Hakkari Bijous found in Zul'Gurub at the Altar of Zanza on Yojamba Isle. When done, speak with Vinchaxa nearby.The destruction of the various Hakkari Bijous is of grave importance to us, so much so that we welcome outsiders of the tribe to do so for themselves!\n\nTake any one of the bijous that you find in Zul'Gurub to the Altar of Zanza and destroy it. For this one time alone, I will give you an additional Honor Token from our tribe; this is above and beyond what you would normally receive.\n\nWitness for yourself the blessings of Zanza!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8241] = { id = 8241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Fiery Flux Supplies via Iron", progress = "Let's not waste more of my precious time with jibber jabber, {race}. It's time to focus on replenishing our dwindling fiery flux supply.\n\nWhat I'm gonna need from you is the following:\n\n*Incendosaur scales.\n\n*Iron bars.\n\n*Coal.\n\nI'll take all that you can offer!\n\nAnd you'll do it fast if you wanna get in good with the Brotherhood.", completion = "There's always room for more fiery flux, junior. Keep it comin'... unless I tell you to stop." }
quests[8242] = { id = 8242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Fiery Flux Supplies via Heavy Leather", progress = "Let's not waste more of my precious time with jibber jabber, {race}. It's time to focus on replenishing our dwindling fiery flux supply.\n\nWhat I'm gonna need from you is the following:\n\n*Incendosaur scales.\n\n*Heavy Leather.\n\n*Coal.\n\nI'll take all that you can offer!\n\nAnd you'll do it fast if you wanna get in good with the Brotherhood.", completion = "There's always room for more fiery flux, junior. Keep it comin'... unless I tell you to stop." }
quests[8243] = { id = 8243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanza's Potent Potables", progress = "With your increased status amongst the tribe comes access to some of our more potent potables.  Behold... these brews are strong in the mojo - blessed by Zanza and fit for adventurers from all walks of life!\n\nI will allow you to choose one from the three I offer; in exchange, I require one Zandalar Honor Token.  Note that only the effects of a single one may course through your spirit at any given time.\n\nLet me know when you're ready to barter!", completion = "A fair trade, my friend - please enjoy the blessings of Zanza with our compliments!" }
quests[8246] = { id = 8246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signets of the Zandalar", progress = "{name} - for someone as exalted among the Zandalar as you are, I have something very special for you.  Direct from our home in the South Seas... the Signets of the Zandalar!  These signets are used to enhance any shoulder item you may possess.  Should you seek might, mojo, or serenity - I have what you need!\n\nI ask for fifteen Zandalar Honor Tokens in exchange for your choice of one signet.  If you have the tokens ready, then I'm ready to make a deal!", completion = "A fair trade, my friend - please accept your signet with the blessing of the tribe!" }
quests[8249] = { id = 8249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junkboxes Needed", progress = "My rogues need to hone their lockpicking skills, and I need locks of adequate difficulty -- the stuff Zan makes us is unfit for all but the lowliest neophytes.\n\nTell ya what, if you bring me 5 Heavy Junkboxes, I'll provide you with some of the finest throwing knives known to roguekind.\n\nYou can unlock the boxes and rifle through them, but you'll have to leave at least a few coins in them... even a rogue in training needs motivation.", completion = "May these knives find a place in someone's heart.\n\nLiterally." }
quests[8250] = { id = 8250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magecraft", description = "Archmage Xylem has been asking around lately... for someone of your experience.\n\nIf you wish to seek him out, you can find him in Azshara.  His tower is built high atop the cliffs, and the only way up is a teleport spell invoked by his arrogant servant, Sanath Lim-yo.\n\nSanath makes camp below his master's tower.  To find him, travel to where Azshara's main road forks at the entrance to the Ruins of Eldarath.  From that spot, head directly north until you reach the cliffs.", objectives = "Seek out Sanath Lim-yo and gain passage to see Archmage Xylem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8251] = { id = 8251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic Dust", description = "The blood elves in Azshara have developed a method for pulverizing the magical items they acquire.  This glittering dust they produce differs from the components normally acquired by a disenchantment spell.\n\nWhen I sent my apprentice to trade for the dust, he was killed without hesitation.  For that, they must pay.\n\nThe time for talk is over, {name}.  Find the blood elves along the cliffs of Azshara and use more \"persuasive\" methods to acquire their glittering dust.", objectives = "Bring 10 Glittering Dust to Archmage Xylem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8252] = { id = 8252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Siren's Coral", description = "Take a look around you.  The ruins and beaches are overrun with spitelash.  Recently, the wretched creatures have learned to recognize the rare components indigenous to Azshara.\n\nSpecifically, I speak of enchanted coral -- they are drawn to it by reasons unknown to me.  Now there is little coral left in the bay, and it is vital to my research.  I need you to separate some enchanted coral from the spitelash sirens and bring it to me.", objectives = "Collect 6 Enchanted Coral and return them to Archmage Xylem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8253] = { id = 8253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy Morphaz", description = "There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz.\n\nYears ago, he overwhelmed me in a bold ambush and consumed my apprentice whole.  While the loss of an apprentice is not unknown to me, this particular one carried an arcane shard of unsurpassed size and quality.\n\nYou must gather powerful allies and delve into the temple.  Destroy Morphaz and recover the arcane shard from his ageless stomach.You will be able to choose one of these rewards:", objectives = "Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8254] = { id = 8254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarion Aid", description = "It is the way of the divine to help those in need.  The how is insignificant -- only the why matters.\n\nThe Cenarion Circle has such a need.  Speak with Ogtinc to lend aid to their plight.  He resides atop the cliffs to the northeast of the Ruins of Eldarath in Azshara.", sourceObjective = "Seek out Ogtinc in Azshara.It is the way of the divine to help those in need. The how is insignificant -- only the why matters.\n\nThe Cenarion Circle has such a need. Speak with Ogtinc to lend aid to their plight. He resides atop the cliffs to the northeast of the Ruins of Eldarath in Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[8255] = { id = 8255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Coursers We Know", description = "The mosshoof coursers of Azshara are magnificent animals who once lived in Felwood.  They naturally resist disease and poison, and were unaffected by the corruption there.  In their ancestral wisdom, they simply chose to leave that sickened place.\n\nIt saddens my heart, but I must ask you to hunt these mighty beasts for me.  Gather four courser glands as the first ingredient for a restorative salve -- a salve we will use to heal Felwood.", objectives = "Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8256] = { id = 8256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ichor of Undeath", description = "For this restorative salve, you must use a simple formula: one part poison, two parts cure.  You have acquired one cure, now you must gather the poison.\n\nPowerful undead, such as the lingering highborne who wander the Ruins of Eldarath, are sometimes so infused with evil that it coalesces into a sickly greenish goo.  To the living, this substance is known as ichor of undeath.\n\nDue to the potency of this vile element, I require only a single ichor.", objectives = "Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8257] = { id = 8257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of Morphaz", description = "Now the last part, the second cure.\n\nThe green drake Morphaz is known to be immune to all forms of poison and disease -- many druids died to bring us this information.  There is no doubt his blood is potent for our needs.\n\nA courier from the Cenarion Circle will take the parts you have already collected while you gather the last.  Summon your allies and seek out the drake's lair in the sunken temple of Atal'Hakkar.  Bring his blood to Greta Mosshoof in Felwood.You will be able to choose one of these rewards:", objectives = "Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8258] = { id = 8258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkreaver Menace", description = "Death Knight Darkreaver lords over the Great Ossuary in the Scholomance.  He threatens to twist the spirit realm to do his own bidding, and he must be stopped!  This is where the scryer you helped make comes into play.\n\nUse the divination scryer in the heart of the Great Ossuary's basement to call forth Darkreaver's spirit minions.  Defeat the spirits and the death knight himself will appear.  {name}, bring me his head!  Only his demise will reverse the damage done to the spirit realm!", objectives = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.\n\nBring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8259] = { id = 8259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A More Fitting Reward" }
quests[8260] = { id = 8260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathor Basic Care Package", objectives = "You've certainly begun to prove yourself to us, {name}.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items will become available to you for purchase.  Rations become available when you are Friendly with us, and bandages when you are Honored.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8261] = { id = 8261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathor Standard Care Package", objectives = "You've certainly begun to prove yourself to us, {name}.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items will become available to you for purchase.  Rations become available when you are Friendly with us, and bandages when you are Honored.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8262] = { id = 8262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathor Advanced Care Package", objectives = "You've certainly begun to prove yourself to us, {name}.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items will become available to you for purchase.  Rations become available when you are Friendly with us, and bandages when you are Honored.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8263] = { id = 8263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defiler's Basic Care Package", objectives = "You've certainly begun to prove yourself to us, {name}.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items will become available to you for purchase.  Rations become available when you are Honored with us, and bandages when you are Revered.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8264] = { id = 8264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defiler's Standard Care Package", objectives = "You've certainly begun to prove yourself to us, {name}.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items will become available to you for purchase.  Rations become available when you are Honored with us, and bandages when you are Revered.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8265] = { id = 8265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defiler's Advanced Care Package", objectives = "You've certainly begun to prove yourself to us, {name}.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Arathi Basin.\n\nAs you continue to prove yourself inside the Basin, you'll find that these items can make the difference between life and death. We need you in top fighting shape if we're to achieve victory!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8266] = { id = 8266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ribbons of Sacrifice" }
quests[8267] = { id = 8267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ribbons of Sacrifice" }
