quests[8269] = { id = 8269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ribbons of Sacrifice" }
quests[8271] = { id = 8271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero of the Stormpike", objectives = "As a hero of the Stormpike, you may choose one item from these recently plun... er, recovered treasures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8272] = { id = 8272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero of the Frostwolf", objectives = "How does it feel, {name}? How does it feel to crush your enemies and watch their lines break apart? It feels good, doesn't it?\n\nYou should be rewarded for this heroic deed, soldier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8273] = { id = 8273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oran's Gratitude", objectives = "Now isn't this interesting? You say you found this tablet on a small, deserted island at The Overlook Cliffs in The Hinterlands, {class}? Very interesting indeed. \n\nI thank you for your efforts in this matter. Our Dark Lady shall be very pleased with this discovery. Here, allow me to reward you proportionately.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8275] = { id = 8275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Back Silithus", description = "Attention, heroes of the Alliance!  The silithid menace has been left unchecked for too long.  Unfettered by any real opposition, they've been preparing all this time for a large-scale expansion.  \n\nCenarion Circle forces are gathering in Silithus to take the fight to these wretched creatures and all able-bodied adventurers are hereby called to join us!\n\nDon't wait until it's too late!  Aid us in the defense of Azeroth! Report to Windcaller Proudhorn at Cenarion Hold for specific instructions!", completion = "Excellent, a new recruit answering the call to arms against the silithid.  Welcome to Cenarion Hold, {class}.  I am pleased to see the words of our emissaries are reaching heroes of your caliber.  You will find no shortage of opportunities to help us in our efforts here and I expect you'll quickly prove to be a valuable ally to our cause.", objectives = "Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8276] = { id = 8276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Back Silithus", description = "Attention, champions of the Horde!  There's a threat we've left unchallenged for too long.  Tremors in the earth near silithid hives all around Azeroth have alerted us to large movements in their numbers as they prepare for expansion.\n\nCenarion Circle forces are gathering in Silithus to take the fight to the silithid before it's too late!  No more shall they defile our lands!\n\nAll able-bodied combatants are to report to Windcaller Proudhorn at Cenarion Hold!  The silithid shall be vanquished!", completion = "Excellent, a new recruit answering the call to arms against the silithid.  Welcome to Cenarion Hold, {class}.  I am pleased to see the words of our emissaries are reaching heroes of your caliber.  You will find no shortage of opportunities to help us in our efforts here and I expect you'll quickly prove to be a valuable ally to our cause.", objectives = "Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8277] = { id = 8277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadly Desert Venom", description = "Beetix Ficklespragg at your service!  My cousin Noggle makes a living gathering rare herbs for Cenarion Hold alchemists.  Or used to, anyway.  He came back from his last trip with a strong poison running though his veins.\n\nI've managed to slow down the venom, but to fully neutralize it I need poison samples from whatever stung him.\n\nNoggle arrived from the north, so I'd bet my shirt stonelash scorpids or sand skitterers did it.  Bring me some stingers and fangs and I'll try to make an antidote for him.", progress = "Are you done collecting those samples?  We could lose Noggle any minute now!", completion = "Cross your fingers, friend!  Here's to hoping we can save Noggle!", objectives = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 8 Stonelash Scorpid Stingers and 8 Sand Skitterer Fangs. Return to her when you have completed the task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8278] = { id = 8278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggle's Last Hope", description = "Blasted!  The antidote didn't work.  Noggle must've been stung by one of the stronger creatures in the far south.\n\nI'm going to need you to go there and get me some more samples, {name}.  The good news is that since their poison is stronger I won't require as many.  The bad news is that there are more kinds of poisonous creatures crawling around the southern area so you'll have to draw from more sources.", progress = "This is our last chance to save Noggle!  Hurry!", completion = "Yes!  It seems to be working, Noggle is coming to.  We owe ya big time!", objectives = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 3 Stonelash Pincer Stingers, 3 Stonelash Flayer Stingers and 3 Rock Stalker Fangs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8279] = { id = 8279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Lexicon", description = "The Twilight's Hammer are not kind to those that leave their ranks.  They hunt me to this day like I'm some sort of beast!  Needless to say, an enemy of theirs is a friend of mine!\n\nTo decipher this Tablet I'll need the book used by their scribes to encode secret messages: the Twilight Lexicon.  It's such an important tool that they keep its three chapters in different locations!  The officers entrusted with the Lexicon are known as Twilight Keepers.  Look for them at the Twilight's Hammer camps.", progress = "Who goes there?  Oh, it's you!  Did you find all the Lexicon chapters yet?", completion = "Yes! These are the parts to the book!  Let's get started then, {name}.\n\nSwap every third word with words from the second chapter... then swap every other word with words from the first chapter...  Wait, did I get that backwards?", objectives = "Bring the three chapters of the Twilight Lexicon to Hermit Ortell in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8280] = { id = 8280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Supply Lines", description = "Cenarion Hold is a location of utmost strategic importance.  I'm convinced that while we hold it our victory over the silithid is guaranteed.  Provided our influx supplies can be maintained, that is.\n\nDesert worms have proven to be more of a threat to our supply caravans than even the silithid themselves.  Just this morning, a large shipment of morrowgrain was ravaged by a group of dredge strikers.  I need you to thin their numbers to ensure our supplies aren't jeopardized.", completion = "You have my sincere gratitude.  Your efforts in helping Cenarion Hold have shown true courage.", objectives = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to kill 15 Dredge Strikers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8281] = { id = 8281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stepping Up Security", description = "Your performance has been truly exemplary so far, {name}.  Our supply lines are not completely safe yet, however.  In the absence of dredge strikers, their larger southern cousins will surely move in to take their place in the north.\n\nYou'll have to kill quite a few dredge crushers to keep them at bay, but we cannot leave the safety of our supply lines to chance.", completion = "Excellent!  You've proven to be a valuable ally in preparing for the war against the silithid.", objectives = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to slay 20 Dredge Crushers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8282] = { id = 8282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggle's Lost Satchel", description = "Where am I?  Where's my bag? *gasp* I must've lost it while fleeing from Deathclasp, the giant scorpid.  In my rush to escape I walked right into a nest of stonelash flayers.\n\nThe satchel I was carrying had all sorts of rare reagents in it.  Without them, me and Beetix won't be able to make the potions that Cenarion Hold needs.  I'm too weak to get up yet, but I can make it worth your while if you bring back my reagents.\n\nI ran into Deathclasp in the southern mountain range, behind Bronzebeard's camp.", progress = "Still haven't found my bag?  Well I should count my lucky stars, at least the poison's been cleansed.", completion = "Yes!  You brought my satchel back.  And my rare reagents are all here!  I'll be in your debt for a long time.", objectives = "Retrieve Noggle's Satchel from the mountains in the south of Silithus and return it to him at Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8283] = { id = 8283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted - Deathclasp, Terror of the Sands", description = "The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity.  She presents a great threat to patrols and expeditions in the southern regions.  Individuals participating in her destruction will be remunerated handsomely.  Inquire with Captain Vish Kozus, at the top of the Cenarion Hold Watchtower, regarding a reward.", progress = "I'll need the creature's pincer as proof of the deed.  No pincer, no reward.", completion = "Excellent!  With Deathclasp gone we're free to use the southern mountain range as a strategic path to circumvent the silithid hives.  Your work is greatly appreciated.", objectives = "Bring Deathclasp's Pincer to Vish Kozus, Captain of the Guard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8284] = { id = 8284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Mystery", description = "A camp of Twilight's Hammer cultists once thrived northwest of here.  If you were to venture there now, you'd find the area swarming with elementals and nothing but scattered pieces of wood and canvas to mark the spot where the camp was.\n\nI've recovered a few fragments of a clay tablet from the site, but I have too few of them to piece together anything useful.  See if you can find the remaining tablet fragments so we can shed some light into the Twilight's Hammer presence here in Silithus.", progress = "The ravaged camp can be found northwest of here.  Come back when you have all the fragments.", completion = "Just as I suspected.  I can decipher individual words in the tablets but they appear to be devoid of any logic or meaning.  It's not unknown for Twilight's Hammer sects to use a code to hide the meaning of their texts; we'll have to go to someone who knows more about this sort of thing.", objectives = "Geologist Larksbane at Cenarion Hold in Silithus wants you to collect 8 Twilight Tablet Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8285] = { id = 8285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deserter", description = "There are rumors of a Twilight's Hammer member called Ortell having deserted his sect.  Word has it he hid in the mountains south of Southwind Village, where he lives as a hermit.  Perhaps you can enlist his help in deciphering the tablet.\n\nTake the restored tablet with you and seek out Ortell.", progress = "You!  How did you find me?  Who are you?  You weren't followed, were you?  Speak!", completion = "I see you're familiar with my old organization.  You must be with Cenarion Hold.  \n\nYou seek information to use against them?  Come closer, perhaps we can be of mutual assistance.", objectives = "Take the restored tablet to Hermit Ortell in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8286] = { id = 8286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Tomorrow Brings", description = "The embrace of death had all but overcome my being when he intervened. He breathed only once upon my maimed body and then waited patiently for the sands of time to cleanse my wounds.\n\n\"Forever you will remain if you must,\" he said, and with those words I was bound as a Watcher.\n\nLook now to the desert. The second war is upon us. You must seek out the resting place of the Bronze. Venture to the Caverns of Time and see if the master has returned. I must be sure before I am able to proceed.", completion = "It is as it should be - the great one has risen. My watch comes to an end...", objectives = "Venture to the Caverns of Time in Tanaris and find Anachronos, Brood of Nozdormu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8287] = { id = 8287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Terrible Purpose", description = "Ok, here we are... a pretty valuable chunk of information, I must say!  I've seen the Cenarion Circle forces arrive at Silithus.  They plan to drive the Twilight's Hammer out, don't they?  This will help.  \n\nTake this parchment to their leader, Commander Mar'alith.  Soon the Twilight's Hammer will be vanquished and I will be outside their grasp for good!", progress = "What is this you bring to me, {name}?", completion = "This is very interesting information indeed, {name}.  This sheds some light on the presence of the Twilight's Hammer in Silithus and will undoubtedly help us in our struggle against them.  Your efforts will be handsomely rewarded, {class}.", objectives = "Take the Decoded Tablet Parchment to Commander Mar'alith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8288] = { id = 8288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only One May Rise", description = "There is no time to waste! A hero must be found! The task I give will require an army to complete but only one may rise from the throng of would be champions to take on the burden and responsibility of an ally of the Brood.\n\nWithin the lair of the Lord of Blackrock is a most cruel beast. The Broodlord Lashlayer guards the Halls of Strife, blocking the way into Nefarian's inner sanctum. Slay the foul aberration and return his head to me. Do this and you may begin the next step of your journey.", progress = "It is the favor of the Brood of Nozdormu that you must earn.", completion = "Could you be the first to earn favor among the Bronze Flight in a thousand years?", objectives = "Return the Head of the Broodlord Lashlayer to Baristolth of the Shifting Sands at Cenarion Hold in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8289] = { id = 8289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talismans of Merit" }
quests[8290] = { id = 8290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vanquish the Invaders", description = "Beyond this tunnel you will find a field of strife and turmoil, young {class}. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, {name}, and I shall reward you.", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8291] = { id = 8291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vanquish the Invaders!", description = "Beyond this tunnel you will find a field of strife and turmoil, young {class}. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, {name}, and I shall reward you.", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8292] = { id = 8292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talismans of Merit" }
quests[8293] = { id = 8293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark of Honor" }
quests[8294] = { id = 8294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quell the Silverwing Usurpers", description = "The wilds of the Ashenvale forest will succumb to the might of the Horde, {race}. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, {name}, and you will be rewarded.", objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8295] = { id = 8295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quell the Silverwing Usurpers", description = "The wilds of the Ashenvale forest will succumb to the might of the Horde, {race}. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!\n\nLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, {name}, and you will be rewarded.", objectives = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8296] = { id = 8296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark of Honor" }
quests[8297] = { id = 8297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Basin Resources!", description = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, {name}.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.", objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8298] = { id = 8298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Resource Crates" }
quests[8299] = { id = 8299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut Arathor Supply Lines", description = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, {name}.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.", objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8300] = { id = 8300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Resource Crates" }
quests[8301] = { id = 8301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Righteous", description = "The Brood of Nozdormu are naturally distrusting of the lesser races. While it is true that you have proven to me that you have the potential makings of a hero, the time has come to prove this to my master.\n\nHive'Ashi, Hive'Zora, Hive'Regal: All swarming with activity and all a threat to our existence. Slay silithid at these hives and take from them a fragment of their carapace. When you can carry no more, return to me and I shall strengthen your resolve.", progress = "There is much history rooted in their distrust of the mortal races; but alas, such is a tale better left for the Brood to tell when the time is right.", completion = "You are not alone, hero. I will now grant you the ability to deputize others to help you in your quest.  If you are to be the champion of your people, you will need assistance in your tasks and duties.", objectives = "Collect 200 Silithid Carapace Fragments and return to Baristolth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8302] = { id = 8302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of the Righteous", description = "Choose your deputies wisely, mortal. Each time you return with your task complete, a new deputy you will be allowed to choose.\n\nWith that said, I require more of the carapace fragments. Waste no time!", progress = "Perhaps one day the whole of Cenarion Hold will be working under your command.", completion = "Well done, hero. You will now be granted the ability to deputize another Agent of Nozdormu.", objectives = "Collect 200 Silithid Carapace Fragments and return to Baristolth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8303] = { id = 8303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anachronos", description = "It is time, {name}.\n\nI must apologize for keeping so much in secret. Enemies abound, even under our very noses. Please, read from this tome and learn. Take the knowledge I give to you and seek out our master.", completion = "You are the hope of Kalimdor, {name}.", objectives = "Seek out Anachronos at the Caverns of Time in Tanaris.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8304] = { id = 8304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dearest Natalia", description = "My dear Natalia has gone missing.\n\nTruth be told, she had been acting strangely for weeks leading up to her disappearance. I had caught her talking to herself when no one was around on more than one occasion. She was adamant that everything was ok and that she must be allowed to continue her research.\n\nShe was last seen heading to Bronzebeard's camp to the south.\n\nMy soldiers are spread too thin, {name}. I need you to go to Bronzebeard's camp and question those dwarves.", completion = "<Commander Mar'alith lowers his head in contemplation.>\n\nWhether she is alive or dead, I must do what is right. She must be found. Alas, I am bound by duty to this outpost. Will you help me once more, {name}?", objectives = "Question Frankal and Rutgar at Bronzebeard's Encampment about the whereabouts of Natalia Mar'alith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8305] = { id = 8305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Long Forgotten Memories", description = "In the southern desert of Silithus, near the sacred barrier, exists a single crystalline tear. This tear serves as a symbol of the great losses beset upon us during the War of the Shifting Sands. Locate this tear and gaze into its depths to gain enlightenment.", completion = "You can feel a great sorrow revolving around this crystal. The force is so powerful that you feel as if you might collapse and die of sadness.", objectives = "Locate the Crystalline Tear in Silithus and gaze into its depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8306] = { id = 8306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Maw of Madness", description = "I need you to venture into Hive'Regal and find what became of my dearest Natalia, {name}. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you speak with those dwarves further. They might be able to give you some tips on dealing with the silithid that inhabit that hive.\n\nAnd {name}, if she truly is as mad as they say... do what you must.", progress = "Natalia?", completion = "<Commander Mar'alith clutches at his chest.>\n\nC'Thun? WHAT is the meaning of all this? What is C'Thun? How could this fiend have turned my sweet Natalia into the monster that you described?", objectives = "Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.\n\nDo not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.\n\nAnd {name}, remember the Commander's words: \"Do what you must...\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8307] = { id = 8307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desert Recipe", description = "Adapting to life in the desert has been difficult to say the least.  Not only do I miss the birds and trees of Auberdine but our food selection is severely limited by this arid environment.  I'm trying to learn about desert herbs, but there aren't many.\n\nI've seen Twilight's Hammer groups from the camp west of here hunt sandworms for food.  Sandworm meat is so bitter though, I can't imagine how they make it palatable.  Keep your eyes open if you go to their camp and let me know if you learn anything.", completion = "This book contains several common recipes and a few unusual ones.  After browsing through it for a few seconds you spot a recipe that involves sandworm meat.", objectives = "Look for information about cooking Sandworm Meat at the Twilight's Hammer camp west of Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8308] = { id = 8308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brann Bronzebeard's Lost Letter", description = "To Whom It May Concern:\n\nIf you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow.\n\nFound information about a Titan. Great battle between him and an Old God. Yes, a bona fide Old God. Found ancient tunnel leading to Ahn'Qiraj. Taking it.\n\nTake this letter to my old camp. Make sure my monkey is getting adequate food, water, and hugs.\n\n-Brann Bronzebeard, Explorer Extreme\n\nP.S. Watch out for crazy Old God worshipping night elf.", progress = "Oh dear.", completion = "Well this explains a lot. If you ever find a way into Ahn'Qiraj, keep an eye out for ol' Brann. I'm afraid that he'll be powerless without his monkey.", objectives = "Take Brann Bronzebeard's Letter to Bronzebeard's Encampment in southern Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8309] = { id = 8309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyph Chasing", description = "After our initial foray into the hives and Mistress Mar'alith's subsequent madness the three hives have been spewing out bugs! The increased activity might be tied into the glyphs covering those strange crystals.\n\nIf I can get rubbings of those crystals and the glyphs on them, we might be able to make sense of this madness.\n\nTake this transcription set  and hit Hive'Regal to the east, {name}. That's the last rubbing I need!", progress = "If you find some crazy night elf lass in there, be sure to give her a kick in the duff.", completion = "I can't make heads or tails of these glyphs. I've never seen anything like it! I hope Frankal's research can shed some light on this mess.", objectives = "Use the Geologist's Transcription Kit to make a Hive'Regal Rubbing from the Hive'Regal Glyphed Crystal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8310] = { id = 8310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Code", description = "I think I can formulate an elixir that will allow us to more readily decipher the glyphs and language of the silithid and Qiraji! \n\nWhat do I need? Glad you asked! I need brains!\n\nNormally I'd need a brain from each silithid type that inhabit the hives. Another brave explorer brought me two of 'em here... and never came back from Hive'Regal.\n\nBring me back a silithid brain from Hive'Regal... and be careful not to end up like him!", progress = "Go play with the monkey, kid. I don't have time for this.", completion = "Outstanding! Don't wander off too far, kid. We might need you to take on another task or two.", objectives = "Obtain an intact Hive'Regal Silithid Brain from any silithid in Hive'Regal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8311] = { id = 8311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallow's End Treats for Jesper!", description = "I'm not allowed to go trick-or-treating.  After Deathwing's attack, I'm lucky Matron Nightingale lets me be this far away.\n\nIf you trick-or-treat for me, I'd trade you the candy you get for some I already have!\n\nEach of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a little gnome named Talvash in Ironforge is handing out candy as well.  When you have all the candy, bring them back to me here!", progress = "Have you finished trick-or-treating yet? I wish I could go, but I don't want to run into Deathwing.", completion = "Wow, you got them all!  You're awesome!\n\nThank you for trick-or-treating for me.  Here, take these pumpkin treats - I think you'll like them a lot!\n\nHappy Hallow's End, {name}!", objectives = "Speak with the innkeepers of Stormwind, Ironforge, and Darnassus, as well as Talvash del Kissel in Ironforge. Perform the tricks they ask of you in exchange for the treats they offer.\n\nReturn to Jesper in front of Stormwind with a Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat, and Ironforge Mint.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8312] = { id = 8312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallow's End Treats for Spoops!", description = "I want to keep trick-or-treating, but I can't because the Matron won't let me.  If you go for me, I'd trade you the candy you get for some I already have!  I think you'd like this candy - it makes you turn into things both funny and scary!\n\nEach of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a troll named Kali Remik in Orgrimmar is handing out candy as well.  When you have all the candy, bring them back to me here!", progress = "Have you finished trick-or-treating yet?  The Matron said we could pick one place to visit, at least there is a lot happening here.", completion = "Wow, you got them all!  You're awesome!\n\nThank you for trick-or-treating for me.  Here, take these pumpkin treats - I think you'll like them a lot!\n\nHappy Hallow's End, {name}!", objectives = "Speak with the innkeepers of Orgrimmar, Undercity, and Thunder Bluff, as well as Kali Remik Orgrimmar's Valley of Spirits. Perform the tricks they ask of you in exchange for the treats they offer.\n\nReturn to Spoops in the Ruins of Lordaeron with a Thunder Bluff Marzipan, Darkspear Gumdrop, Orgrimmar Nougat, and Undercity Mint.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8313] = { id = 8313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing the Knowledge", description = "While the recipe for cooking sandworm meat is legible, it contains references to herbs and spices you've never heard of.  Calandrath might have enough knowledge of the plants that grow in the desert to make sense of it.", progress = "Did you learn the recipe?  You won't keep it to yourself, I hope!", completion = "Let's have a look at that...\n\nThis seems simple enough.  They have their own names for some of the herbs, but those are simple enough to figure out.  Here, let me show you!", objectives = "Bring the Torn Recipe Page to Calandrath at the inn in Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8314] = { id = 8314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unraveling the Mystery", description = "We're on the verge of a breakthrough, {name}! The rubbings you recovered have allowed us to recreate the glyphs on this crystalline prism. They are apparently a means for the Qiraji and other unknown entities to communicate various messages to the silithid.\n\nUnfortunately, that is all we could get out of the glyphs. We need to find a way to unlock the messages hidden within the crystals.\n\nTake the glyphed crystal prism to Geologist Larksbane at Cenarion Hold.  She might be able to help.", progress = "Oh my! What do you have there, {name}?", completion = "The reason the dwarves could not decipher the glyphs is because there is nothing to decipher. The shifting outer layer of the prism must properly align with the inner crystal's markings in order for the message to be transmitted. Clever...\n\nWhile we should be able to translate this data, we must first unlock the code. There is only one clue on the surface of the prism - assuming the rubbings were transferred correctly - and it looks grim.", objectives = "Deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8315] = { id = 8315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Calling", description = "The glyphs illustrate an emissary of the Qiraji meeting with three silithid at the bones of a large dragon. Above the glyphs is what I can only assume to be a code of some sort. This code might very well be the key to summoning the emissary.\n\nI will create a copy of the glyph code that you must use in the sand at the Bones of Grakkarond. If I am right, the Overlords will come thinking that new data is ready for transmission. Strike them down and confront the emissary. He holds the key to the crystals...", progress = "You must take the opportunity as it presents itself and strike!", completion = "I hold 20,000 years of history in my hands, {name}!", objectives = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.\n\nYou have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.\n\nAssemble an army for this task, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8316] = { id = 8316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armaments of War", objectives = "War comes, {name}, and with it comes untold horrors. You have done all that could be asked of you and for that you should be rewarded.\n\nShould this... this prophecy ever come to pass...\n\n<Geologist Larksbane turns pale.>\n\nThe future of us all could be at an end.\n\nThese armaments will prove invaluable to your campaign in this desert.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8317] = { id = 8317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kitchen Assistance", description = "That recipe sure will come in handy.  I'd better get to work so I can have some smoked desert dumplings ready for today.  I could use a hand in making some, I'll make it worth your while.", progress = "How are those dumplings coming along?", completion = "Excellent!  You're a life saver.  These dumplings turned out to be quite good.  Didn't really expect such good taste from the Twilight's Hammer.", objectives = "Calandrath at Cenarion Hold needs a batch of 10 Smoked Desert Dumplings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8318] = { id = 8318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret Communication", description = "Some of the Twilight's Hammer cultists carry around little papers with gibberish written on them.  I want you to bring me a stack of them, {class}.\n\nI can't figure out what the gibberish means, but that's not the point!  These papers are how their different groups communicate secretly.  The more texts we take out of circulation, the less they can communicate!", progress = "Did you bring me some texts?", completion = "Excellent!  I'll stash these away, maybe they'll be useful later.", objectives = "Bring 10 Encrypted Twilight Texts to Bor Wildmane in Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8319] = { id = 8319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Twilight Texts", progress = "Keep bringing me texts.  We'll soon force the Twilight's Hammer out of Silithus.", completion = "Excellent work!  I'll put a good word in for you." }
quests[8320] = { id = 8320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Geolords", description = "The Twilight's Hammer, an insane cult bent on destruction, set up camps in Silithus and perform rituals day and night.  We do not yet know their plans, but we do think they are somehow linked to the pulsing red crystals spread across the desert.\n\nAlthough their mystery may one day be solved, we must first deal with their immediate threat.  Go to their camps to the west and seek out Twilight geolords.  They are the heads of these serpents; that is where we must strike!", completion = "That was a task well performed, {name}.  Your slaying of the Twilight geolords must have dealt a grievous blow to the cult.  Let us hope their plans are slowed...", objectives = "Kill 10 Twilight Geolords, then return to Huum Wildmane in Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8321] = { id = 8321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyral the Vile", description = "We have discovered another base of operations for the Twilight's Hammer.  It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus.  The local leader of the cult, Vyral the Vile, haunts that cave - it is he who you must next defeat.  When you have done this, bring me his signet ring.\n\nFortune to you, {name}.  The horrors of Twilight's Run are formidable indeed.", progress = "{name}, have you yet defeated Vyral the Vile?  Do you have his signet ring?", completion = "You've done it!  Vyral is killed!  This can only mean doom for the Twilight Hammer's operations in Silithus.  There may be more of them scurrying about, but the blow you dealt to the cult today is one from which they will not easily recover.", objectives = "Slay Vyral the Vile and obtain Vyral's Signet Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8322] = { id = 8322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotten Eggs", description = "The humans of Southshore love their ale, and as such they prize the ale served at the Southshore Inn.  With the chaos of Hallow's End now upon them, we can use it to ruin their latest batch of beverages for weeks - if not months to come!\n\nTake these rotten eggs and place them in the main brew keg inside the Southshore Inn.  Your presence alone will cause strife, so be prepared to defend yourself!\n\nOnce you've given Southshore a taste they'll not soon forget, return to me here at the festival!", objectives = "Place the Rotten Eggs in the main brew keg located inside the Southshore Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8323] = { id = 8323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Believers", description = "Now that I have the Twilight Lexicon in my possession, there is a small favor I'd like to ask of you.\n\nMy former organization has a secret encoded bulletin they circulate on a monthly basis.\n\nIf they make any progress searching for me or if they call off the search, word will be published on the True Believer.\n\nAlthough this information is obviously valuable to me, the publication contains other useful information that I can share.  Bring me any encoded texts you find on Twilight's Hammer members.", progress = "Did you find any encrypted texts?  I'm quite curious to read this month's True Believer.", completion = "Excellent!  I will get to decoding these as soon as possible.  If I find anything of interest I'll find some way to get the information to you.", objectives = "Hermit Ortell wants you to bring him 10 Encrypted Twilight Texts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8324] = { id = 8324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Believing", progress = "Find any more encrypted texts?  Bring me a good batch of them, this decoding work takes some time.", completion = "Excellent!  I can't wait to read these.  Please do keep bringing the encrypted texts here if you find them." }
quests[8325] = { id = 8325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Sunstrider Isle", description = "The sooner you begin your education, {name}, the better for us all.  There is little room for error, so listen closely.\n\nThe Burning Crystals - the green floating objects to the west of the Sunspire here - have long been used to power the isle's experimentations.  The mana wyrms were their guardians, but the Scourge invasion of Quel'Thalas has driven them errant from our lack of magical control over them.\n\nThere is little choice but to thin their numbers for reclamation.  Do this, then return to me.", progress = "Our work in rebuilding our society begins here, {name}.  Once we are able to secure our home, we can look outward and upward.", completion = "You have successfully completed your first task; for that, you are to be congratulated.  Such success gives me faith that you will turn out better than those young blood elves who fail to heed the lessons of their masters.  Continued success will be rewarded - not only with knowledge, but also with tangible rewards as well.\n\nYour work here, however, is not finished.  There is much more to learn, my young friend...", objectives = "Kill 6 Mana Wyrms; they are located close to the Burning Crystals that are adjacent to the tower and gazebo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8326] = { id = 8326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfortunate Measures", description = "Your effort has made something clear that, honestly, I wish were not true.  The unchecked power of the Burning Crystals has maligned a much larger swath of the isle's natural balance than I thought.  We must now take on more unfortunate measures to reclaim control.\n\nThe nearby lynxes have succumbed to the influence of the crystals, and they must be put down.  Bring their collars, {name}, as I may yet be able to fashion a magical restraint to turn some back from being uncontrolled.", progress = "It gives me no pleasure to ask you to destroy these beasts.  While in times past we have lived in relative harmony with woodland creatures, these are different times.  The first order of business for all sin'dorei is survival; make sure you remember that.", completion = "The tower and surrounding areas should now be relatively secure, though only for the time being.  You have done well in providing us with a buffer of security, but we will need to reassert control over the entire isle if we are to survive here in the long run.  This will involve tackling much greater threats than errant mana wyrms and lynxes.\n\nTake this, {name} - you will no doubt make good use of it for the tasks to come.", objectives = "Collect 8 Lynx Collars from slain Springpaw Lynxes and Springpaw Cubs. Return to Magistrix Erona on Sunstrider Isle when you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8327] = { id = 8327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Lanthan Perilon", description = "You are to report to my assistant, Lanthan Perilon.  He will instruct you on what needs to be done next.  While we here at the Sunspire will continue to rein in the Burning Crystals, you will be focused on a more pressing matter concerning Falthrien Academy.  Lanthan will explain fully when you speak to him.\n\nSimply walk west of here along the path, and you should see him standing close by.\n\nGood luck, {name} - your continued successes shall be rewarded.", completion = "Magistrix Erona told me you'd be along quick enough, {name}.  The Falthrien Academy to our west - the huge floating building with the ornate spires - is in bad shape.  You're going to be leading the effort to recapture it from one of the Wretched - a {race} who has forever succumbed to their basest cravings.\n\nI hope you're ready to work.  This is not only going to be a lesson about danger, but also of what happens when you forsake the realities of who you are.", objectives = "Speak with Lanthan Perilon on Sunstrider Isle; he is standing close to the path running west away from the Sunspire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8328] = { id = 8328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young mages here on Sunstrider Isle, your trainer is Julia Sunstriker.  Speak with Julia and see what training she has available for you.  The things she will teach do have a cost, so bring some coin with you.\n\nJulia - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", completion = "Ah, {name} - I believe you're one of the new mages here on the isle, yes?  Well, you've come to the right place.  If arcane mastery is what you seek, then I can provide such knowledge - as long as you have the wherewithal to handle training costs and the capacity to focus on the lessons I'll be teaching.\n\nLet's get started!", objectives = "Speak with Julia Sunstriker - the Mage class trainer - inside the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8329] = { id = 8329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warrior Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young warriors here on Sunstrider Isle, your trainer is Delios.  Speak with him and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.\n\nDelios - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", completion = "Welcome to the Sunspire, young {class}!  Mastery of weapons and battle tactics begins here and now - all I ask of my pupils is that they cover payment for training costs that may come up, and that they are as good of a listener as they are an aspiring {class}.  The lessons I have to teach are extensive, and I don't like to repeat myself unnecessarially.\n\nLet's get to it then!", objectives = "Speak with Delios, the warrior class trainer, inside the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8330] = { id = 8330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "olanian's Belongings", description = "With all the chaos happening here at the Sunspire, I haven't had a chance to collect my belongings I've left outside at various places on the isle.  I must maintain my vigil over the Sunwell here, so I'll ask you to collect them in my stead.\n\nI need my scrying orb, my scroll of Scourge magic, and my journal.  Use this satchel for some extra space, as my things are rather bulky.  Return them to me and I'll give you a little something - you know, for the effort; you can keep the satchel as well!", progress = "Have you had a chance to find my belongings?  Once we reassert our dominance over Sunstrider Isle, I will need them in my work.  For now though, I must maintain my watch over the Sunwell... or what remains of it.", completion = "Well done - I knew you'd be perfect for the task.  Once it's safe to make use of our outdoor facilities on the isle, I'll be putting these things to good use.\n\nLike I mentioned, please feel free to keep the satchel.  Also, you may find this piece of armor to be useful.  Consider it ample compensation for a simple task performed dutifully!", objectives = "Collect Well Watcher Solanian's Scrying Orb, his Scroll of Scourge Magic, and his Journal. They are found on Sunstrider Isle by the pond, the fountain, and one of the Burning Crystals. Return them to the Well Watcher at the Sunspire on Sunstrider Isle when you've collected them all.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8331] = { id = 8331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aurel Goldleaf", description = "{name}, although we had hoped the Twilight's Hammer's operations in Silithus were slowing... we were, regrettably, mistaken.  Through continued forays against the cult, we have learned that an even darker power, the Abyssal Council, controls the Hammer through the arcane wind stones dotted amongst the cult's camps.  Your next action, {name}, will be against the Abyssal Council.\n\nSpeak with the craftsman Aurel Goldleaf, in the eastern section of Cenarion Hold.  Her skill will be needed for this next gambit.", completion = "{name}, good day.  I was told you will pit yourself against the Abyssal Council?  If that is so, then listen closely to my next words...", objectives = "Speak with Aurel Goldleaf in Cenarion Hold.{name}, although we had hoped the Twilight's Hammer's operations in Silithus were slowing... we were, regrettably, mistaken. Through continued forays against the cult, we have learned that an even darker power, the Abyssal Council, controls the Hammer through the arcane wind stones dotted amongst the cult's camps. Your next action, {name}, will be against the Abyssal Council.\n\nSpeak with the craftsman Aurel Goldleaf, in the eastern section of Cenarion Hold. Her skill will be needed for this next gambit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8332] = { id = 8332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dukes of the Council", description = "We think it is possible to use a wind stone to ambush a duke of the Abyssal Council.  To do this, however, one must commune through the wind stone, and convince the council you are a middle ranked leader of the Twilight's Hammer.  \n\nSuch a gambit requires a replica of the cult's medallion of station.  I can create the medallion, but I will need a large brilliant shard, and crests worn by the Abyssal Templar.\n\nBring these to me and I will do the rest.", progress = "Do you have the shard and the crests, {name}?  I will need them to make the twilight cultist's medallion of station.", completion = "Ah, very good.  I've been working on the medallion - now with these last ingredients, I'll be done in just a few moments...\n\nThere we are.  Here is the medallion, {name}.\n\nYou'll need to wear this when you activate one of the Twilight's Hammer's wind stones.  Put this on, along with the rest of the twilight trappings, and the Abyssal Council will see you as one of their cultist underlings.", objectives = "Bring 1 Large Brilliant Shard and 3 Abyssal Crests to Aurel Goldleaf in Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8333] = { id = 8333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medallion of Station", progress = "If you need another Twilight cultist's medallion of station, then I am happy to oblige.  I will, however, need another brilliant shard and some abyssal crests...", completion = "Here you are, {name}.  One more Twilight medallion of station.  Use it well, and I wish you luck against the Abyssal Council!" }
quests[8334] = { id = 8334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggression", description = "Before sending you to the Academy, I want you on another task that needs to be dealt with immediately.  Once used to aid us in the gardening of Sunstrider Isle, the bestial tenders now have grown out of our control.  Clear them out with due haste, but be warned - their lack of control has made them aggressive.  It is such aggression that forces us to put down these once-gentle servants.\n\nIt doesn't please me to ask you to do such a task, but survival is survival.  I'll mourn later.", progress = "It is better you learn about survival - and the costs of survival - now rather than later.  Making hard choices is something you're going to have to get used to as a {race}.\n\nNo one was there for us when the Scourge ripped our home in two.  It was us and us alone who pulled ourselves up by the bootstraps.", completion = "While the deaths of the tenders give me no joy whatsoever, it does show me that you're ready for the most important task you'll do here on Sunstrider Isle.  Take this and put it to good use; you'll need good items and sharp wits for the task ahead.  Our reassertion of control over the island depends on it.", objectives = "Kill 7 Tenders and 7 Feral Tenders, and then return to Lanthan Perilon on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8335] = { id = 8335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felendren the Banished", description = "A betrayer of our people resides atop Falthrien Academy to the southwest.\n\nFelendren is his name, and he was banished from blood elf lands for failing to heed the warnings of our teachers and elders.  He is the worst of our society, as he lives only to feed his insatiable magical addictions.  He refused to learn control; he is a shell of his former self - one of the Wretched - and he is a threat to the Sunspire.\n\nDestroy him and the wraiths he uses as minions.", progress = "Heed well this warning - Felendren the Banished is only a symptom of a much larger problem.  His demise will solve our immediate concerns, but all blood elves share the potential same fate as him if we let our addictions get the best of us.", completion = "Felendren's head... you are to be commended, {name}.  You've succeeded where others, like Felendren, have utterly failed.  Perhaps you are truly ready to be a contributing member of {race} society.\n\nYour success here means that you are capable of surviving the greater threats that lurk in Eversong... and believe me, there are plenty to face.", objectives = "Kill 8 Arcane Wraiths and 2 Tainted Arcane Wraiths, as well as Felendren the Banished; they are located in the Falthrien Academy. Bring Felendren's Head to Lanthan Perilon on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8336] = { id = 8336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fistful of Slivers", description = "It's a shame that we've lost control of many of the creatures here on the island.  This was once a tranquil place of study and research.  Now it's all we can do to keep from being attacked by our own creations!\n\nI'm going to offer you a chance to receive a magical boon in exchange for some collecting work on your part.  Bring me a stack of arcane slivers that are found on the mana-using creatures of Sunstrider Isle, and I will cast a spell on you that should aid your adventures on the isle.", progress = "Many of the creatures here on the isle were at one point bound into non-aggression and complacency by our magical skills.  When the Scourge destroyed the Sunwell, our hold over these creatures shattered.  Arcane slivers are the remnants of the control we once had, and as such might be usable in fashioning a new device to aid us in regaining their control.\n\nBetter still, perhaps the slivers could be used to see what malaise the isle truly suffers under...", completion = "Splendid - these will do nicely.  I've been doing quite a bit of thinking on the current malaise Sunstrider Isle suffers under.  One possible course of action I had pondered was to collect these arcane slivers from the beasts on the isle.  In doing so, they could be experimented on; this would provide a potential source of culpability.\n\nAnyway, I will tend to the research.  Allow me to place this incantation on you.  I believe you'll make good use of it!", objectives = "Collect 6 Arcane Slivers from any creature on the isle that uses mana, and then return to Arcanist Ithanas on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8338] = { id = 8338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tainted Arcane Sliver", description = "You've found an odd sliver of crystallized mana on the corpse of the tainted arcane wraith.  The sliver is different than others you may have seen in that it is as dark and sinister-looking as the wraith you looted it from.  Just holding it gives you a sense of unnatural foreboding.\n\nArcanist Helion at the gazebo of the Sunspire on Sunstrider Isle just might be someone who would have a use for the sliver.", progress = "From your demeanor, you seem to be on a matter of some urgency.  Is there something specific I can assist you with?", completion = "This is... most interesting.  And when I say interesting, I mean more disturbing than anything else.\n\nOur efforts to reassert control over the isle in the time following the destruction of the Sunwell have been a challenge.  I suspect that whatever foul source is corrupting the isle is at the heart of it all; this sliver may be of some aid in uncovering what's really going on.\n\nYou were wise to bring this to me, {name}.  Take this as compensation for your diligence.  Thank you.", objectives = "Bring the Tainted Arcane Sliver to Arcanist Helion at the gazebo of the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8341] = { id = 8341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lords of the Council", description = "Lords of the Abyssal Council can only be summoned through the greater wind stones, and only the top ranking members of the Twilight's Council may speak to them.  But... I have found a way to upgrade your disguise and fool the Abyssal Lords!\n\nThe disguise calls for a ring of lordship, worn only by the highest members of the cult.  I will craft one for you if you can bring me large brilliant shards and abyssal signets.", progress = "Do you have the shards and the signets, {name}?  I will need them to create the ring of lordship.", completion = "Thanks.  Just one moment and I'll have that ring ready for you...\n\nThere it is.  Now you're ready.\n\nBe sure to wear this ring, along with a medallion of station and the rest of the twilight trappings, when you activate a greater wind stone.  Do that, and the Abyssal Council will think you one of their servants.  Then, perhaps you can lure one into an ambush!", objectives = "Bring 5 Large Brilliant Shards and 3 Abyssal Signets to Aurel Goldleaf in Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8342] = { id = 8342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Ring of Lordship", progress = "{name}, if you plan to go after the Abyssal High Council again, then you'll need another Twilight ring of lordship.  Bring me more shards and signets and I'll make one for you.", completion = "Ah, I see your convictions are strong.  Not many will face that council of fiends!\n\nHere's your ring, {name}.  May your will, and your fortune, stand firm." }
quests[8343] = { id = 8343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldleaf's Discovery", description = "{name}, Aurel Goldleaf thinks she's found a way to summon and defeat a ruling member of the Abyssal Council!  Such a task will be dangerous, but you have earned great respect amongst the Cenarion Circle.  We know that if anyone can do it, you can.\n\nMay fortune go with you, {name}.  Speak with Aurel when you are ready.", completion = "What Huum says is true.  I believe I know how to summon a lord of the Abyssal Council!  Listen on, and I will explain...", objectives = "Speak with Aurel Goldleaf in Cenarion Hold.{name}, Aurel Goldleaf thinks she's found a way to summon and defeat a ruling member of the Abyssal Council!  Such a task will be dangerous, but you have earned great respect amongst the Cenarion Circle. We know that if anyone can do it, you can.\n\nMay fortune go with you, {name}. Speak with Aurel when you are ready.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8344] = { id = 8344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windows to the Source", description = "Heed my words, young one - there is a taint about this island, and it is far more potent than the remnants of the Scourge.\n\nI believe there is a true demonic presence on the isle.\n\nWest of here are the spires of Falthrien Academy.  The arcane wraiths that infest it are a window to the source of demonic power.  You are to bring me the essences of tainted and untainted wraiths.\n\nIn exchange for your obedience, I'll teach you how to summon an imp companion - your first of many as a warlock.You will learn:", objectives = "Bring 4 Wraith Essences and 1 Tainted Wraith Essence to Summoner Teli'Larien at the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8345] = { id = 8345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Shrine of Dath'Remar", description = "Day after day I stand here, watching, waiting.  I've been accused of dwelling too much on our past, while my eyes look to the horizon.  But it is my firm belief that each visitor to this island should honor those who have sacrificed all so that they may continue to do so.\n\nDath'Remar Sunstrider was our first king.  He led us here from Kalimdor through the Maelstrom.\n\nSeek out his shrine to the west and do not return to me until you have read the plaque upon it in his honor.", completion = "Ah, {name} - thank you for sharing your experience at the Shrine of Dath'Remar.  First off, you should be commended for your sense of duty and respect - it will serve you well not only here, but in all of Azeroth as well.\n\nAs for the odd sensation, it is no doubt a contributing part of the taint that has befallen Sunstrider Isle.  We shall keep an eye on it; thank you for alerting us to it!", objectives = "Read the plaque on the Shrine of Dath'Remar and then return to Well Watcher Solanian at the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8346] = { id = 8346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "hirst Unending", description = "If there is only one lesson you deign to remember from your time on Sunstrider Isle, let it be this - control your thirst for magic.  It is a thirst unending, {name} - what you absorb must be controlled and released via Arcane Torrent.  Failure is to become one of the Wretched... hopelessly addicted and insane.\n\nSeek out a mana wyrm and unleash your Arcane Torrent upon it.  Learn to master your power. When you have sufficiently released an Arcane Torrent, return to me.", completion = "You've done well today, {name}.  Your willingness to learn shows that you may very well rise above the unyielding cravings you must endure as a {race}.\n\nRest not on your laurels, young one, but instead seek to master what you have learned.  Only through diligence will we as a race survive.\n\nTake this - it may be of some use to you.  Go now, and bring glory once more to our people.", objectives = "Use your Arcane Torrent racial ability on a Mana Wyrm, then return to Arcanist Helion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8347] = { id = 8347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Outrunners", description = "Magistrix Erona wanted you to head over to Silvermoon City in order to aid our reclamation efforts there... that is, once you had successfully addressed the situation at Falthrien Academy.  You did not disappoint us, {name}.\n\nOn your way to Falconwing Square, south of here, you should speak with Outrunner Alarion.  She's not far from the bridge.\n\nThe Outrunners take care of shuttling goods between here and the mainland, and since you've proven to be so resourceful, they could use your assistance.", completion = "Well hello there, {class}!  I heard that a resourceful young {race} formerly in the service of Magistrix Erona might be making their way down here to help us Outrunners out.  We certainly welcome the help, especially from someone who's proven to be so competent.\n\nI hope you're interested in running an errand or two for us.", objectives = "Speak with Outrunner Alarion near the bridge leading south of Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8348] = { id = 8348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signet of the Dukes", description = "Huum tells me you've figured out how to summon the Abyssal Dukes!  That's quite an accomplishment.\n\nYou know what else would be quite the accomplishment?  Smashing up one of those things really good.  That'll cause an impression on their underlings, if you know what I mean.  Bring back its signet as proof of the deed.", progress = "How did it go with the Abyssal Duke?  Did it hit hard?", completion = "I knew you were a tough {class} the minute I saw you walk into Cenarion Hold.  Keep it up!", objectives = "Bring the Abyssal Signet to Bor Wildmane in Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8349] = { id = 8349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bor Wildmane", description = "Now that you have a medallion and can summon an Abyssal Duke, speak with Bor Wildmane.  He will set you on a task against the Abyssal Council.\n\nGood luck, {name}.  And if you ever need more medallions, return to me.", completion = "Good to see you again, {class}!  So you had a medallion made?  Good -- you'll need that for your next quest...", objectives = "Speak with Bor Wildmane in Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8350] = { id = 8350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Completing the Delivery", description = "The death of another outrunner is a true tragedy, but it's a risk we all accept when we take the job.  Magistrix Erona at the Sunspire needs to get this package to the inn at Falconwing Square, and she needs it there as soon as possible.\n\nWe're short handed and I don't have anyone else available that can cover for us.\n\nI'm not going to lie to you; the path to Falconwing Square can be extremely dangerous if you leave the safety of Dawning Lane.  Do you feel up to the task, {name}?", progress = "Welcome to my inn, {class}.  Am I to understand that you have something for me?", completion = "Thank you, I do appreciate the prompt delivery.\n\nWhile you're here, please make yourself comfortable.  If you haven't done so already, feel free to get a hearthstone and bind yourself here.  Using a hearthstone will allow you to recall to an inn once every half-hour.  If you ever lose your hearthstone, simply return to any inn - an innkeeper will gladly get you a new one.", objectives = "Deliver Erona's Package to Innkeeper Delaniel inside the inn at Falconwing Square in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8351] = { id = 8351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bor Wishes to Speak", description = "Now that you can disguise yourself as a ruling member of the Twilight Council, I am certain Bor Wildmane will want to speak with you.  Go see him, and prepare yourself for a very difficult mission...", completion = "Yes, that's right, {name}.  I have a very tough task ahead...", objectives = "Speak with Bor Wildmane in Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8352] = { id = 8352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scepter of the Council", description = "Huum and I were just talking about you.  He tells me you're just about ready to try your hand at fighting an Abyssal Lord!\n\nI must tell you this is a very dangerous endeavor.  You'd better bring backup.  And I don't mean one or two of your friends, I'm talking about a top-notch, battle-ready fighting force.  If your friends are as good as you, you might even defeat it!\n\nIf you do - and I'll want evidence, as always - I'll give you a truly great reward.", progress = "Well, how did it go?  I'd do anything to leave my post and wrestle one of those things myself!", completion = "You... you did it!  You did it, {name}!  Here!  Take this.  It's the biggest chest we had lying around and I filled it with some of the best stuff we found.", objectives = "Bring an Abyssal Scepter to Bor Wildmane in Cenarion Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8353] = { id = 8353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chicken Clucking for a Mint", description = "Ah, trick-or-treating on behalf of a child, are we?  I was going to say, you're a little old to be rummaging about for candies...\n\nWell, for my treat - an Ironforge Mint - you will need to... cluck like a chicken!  Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me!\n\nWell {class}, are you up to the challenge or not?!  Time to earn your treat!", progress = "I'm waiting...", completion = "Too funny!  Well done, {name}!  Here's your treat.\n\nHappy Hallow's End!", objectives = "Do a chicken emote at Innkeeper Firebrew, and in exchange you'll receive an Ironforge Mint!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8354] = { id = 8354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chicken Clucking for a Mint", description = "Ah, trick-or-treating on behalf of a child, are we?  I was going to say, you're a little old to be rummaging about for candies...\n\nWell, for my treat - an Undercity Mint - you will need to... cluck like a chicken!  Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me!\n\nWell {class}, are you up to the challenge or not?!  Time to earn your treat!", progress = "I'm waiting...", completion = "Too funny!  Well done, {name}!  Here's your treat.\n\nHappy Hallow's End!", objectives = "Do a chicken emote at Innkeeper Norman, and in exchange you'll receive an Undercity Mint!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8355] = { id = 8355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incoming Gumdrop", description = "A trick-or-treater!  Huzzah!\n\nWell now, even though you're doing something noble and collecting candies for a child, I can't let you off the hook that easily.  I have a yummy Gnomeregan Gumdrop to give to the sick child... if you make a train noise for me!  Haha, yes, that'll be the trick!  The price of this gumdrop is one train noise!\n\nChugga-chugga, {class}!", progress = "Well, go ahead now...", completion = "Woo-woo!  Well done, {name}!  Here's your treat.\n\nHappy Hallow's End!", objectives = "Do a train emote at Talvash del Kissel, and in exchange you'll receive a Gnomeregan Gumdrop!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8356] = { id = 8356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flexing for Nougat", description = "That's an... interesting costume you have on.  Even though you're being nice and helping a child trick-or-treat this year, I'm afraid I'm going to have to ask you to perform a trick for me!\n\nLet's see... you look so strong and buff in that... costume... let's see you flex!  Yes, go on now and flex for me, strong <man/woman>!\n\nWhen and only when you flex, I'll give you some tasty Stormwind Nougat.  It's a great Hallow's End treat.", progress = "No candy until you flex for me, {name}...", completion = "You are truly mighty, haha!  Well done, and thanks for being such a good sport.  Here's your candy.\n\nHappy Hallow's End, {name}!", objectives = "Do a flex emote at Innkeeper Allison, and in exchange you'll receive Stormwind Nougat!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8357] = { id = 8357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dancing for Marzipan", description = "Even though you're trick-or-treating on behalf of a child, you still need to perform a trick for the treat!  We can't very well change the tradition, now can we...\n\nI believe the cost of a piece of marzipan nowadays is to bust out and DANCE!  That's right, let me see your moves!  Dance for me, and I'll give you some tasty marzipan!", progress = "You know how to dance, don't you?  Try by putting your right foot in... then your right foot out... your right foot in... shake it all about...", completion = "You're quite the dancing machine, {name}!\n\nHere's your treat for being such a good sport.  Happy Hallow's End, and give my best to your sick little friend!  I hope they get better soon.", objectives = "Do a dance emote at Innkeeper Saelienne, and in exchange you'll receive Darnassus Marzipan!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8358] = { id = 8358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incoming Gumdrop", description = "A trick-or-treater!  Yeah mon!\n\nWell now, even though you're doing something noble and collecting candies for a child, I can't let you off the hook that easily.  I have a yummy Darkspear Gumdrop to give to the child... if you make a train noise for me!  Haha, yes, that'll be the trick!  The price of this gumdrop is one train noise!\n\nChugga-chugga, {class}!", progress = "Well, go ahead now...", completion = "Woo-woo!  Well done, {name}!  Here's your treat.\n\nHappy Hallow's End!", objectives = "Do a train emote at Kali Remik, and in exchange you'll receive a Darkspear Gumdrop!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8359] = { id = 8359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flexing for Nougat", description = "That's an... interesting costume you have on.  Even though you're being nice and helping a child trick-or-treat this year, I'm afraid I'm going to have to ask you to perform a trick for me!\n\nLet's see... you look so strong and buff in that... costume... let's see you flex!  Yes, go on now and flex for me, strong <man/woman>!\n\nWhen and only when you flex, I'll give you some tasty Orgrimmar Nougat.  It's a great Hallow's End treat.", progress = "No candy until you flex for me, {name}...", completion = "You are truly mighty, haha!  Well done, and thanks for being such a good sport.  Here's your candy.\n\nHappy Hallow's End, {name}!", objectives = "Do a flex emote at Innkeeper Gryshka, and in exchange you'll receive Orgrimmar Nougat!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8360] = { id = 8360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dancing for Marzipan", description = "Even though you're trick-or-treating on behalf of a child, you still need to perform a trick for the treat!  We can't very well change the tradition, now can we...\n\nI believe the cost of a piece of marzipan nowadays is to bust out and DANCE!  That's right, let me see your moves!  Dance for me, and I'll give you some tasty marzipan!", progress = "You know how to dance, don't you?  Try by putting your right foot in... then your right foot out... your right foot in... shake it all about...", completion = "You're quite the dancing machine, {name}!\n\nHere's your treat for being such a good sport.  Happy Hallow's End, and give my best to your little friend!", objectives = "Do a dance emote at Innkeeper Pala, and in exchange you'll receive Thunder Bluff Marzipan!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8361] = { id = 8361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssal Contacts", description = "We've seen the Twilight's Hammer cultists performing rituals to summon powerful elemental nobles.  We don't know if these are the beings the cultists worship or if they act as intermediaries to even more powerful forces.  One thing is for sure: they are receiving orders from these elementals.\n\nI want you to find a way to contact an Abyssal Templar and give it a proper beating!  Nothing throws the troops in disarray like taking out the chain of command.  Bring back proof while you're at it.", progress = "Did you finish the job?", completion = "Hah!  You did it, {name}!  The Twilight's Hammer will soon be crushed!", objectives = "Bor Wildmane at Cenarion Hold in Silithus wants you to destroy an Abyssal Templar and bring him an Abyssal Crest as proof of the deed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8362] = { id = 8362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssal Crests", progress = "You've proved you can handle yourself in a fight, {name}.  Let's keep the pressure up on the Twilight's Hammer.  Go fight some more Abyssal Templars, I'll reward you with some of the stuff Huum and I have found in battle.", completion = "You've done well!  That's less Templars for me to worry about.\n\nHere you go, {name}.  Hope there's something useful in there for you." }
quests[8363] = { id = 8363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssal Signets" }
quests[8364] = { id = 8364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssal Scepters" }
quests[8365] = { id = 8365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirate Hats Ahoy!", description = "You're the help the Cartel sent? I suppose you'll do. Listen carefully {class}. As you know, I am a procurer of fashionable apparel for the elite of Azerothian society.  Kings and Queens, Warchiefs and, well whatever the Horde calls their queens, all wear what I choose is in style.  And they pay through the nose for it, which is the best part.\n\nSo here's what's going to happen. You head down to Lost Rigger Cove and acquire a lot of pirate hats by whatever means. Do you think you can handle that?", progress = "Do you have all 20 hats? I don't believe you, let me see them. They better be in pristine condition!", completion = "Oh you're a darling, even if it did take you longer than I am accustomed to. This shipment should make me quite a bit of money once I've cleaned and personalized these hats. And seeing as I'm always willing to reward work that's well done, here's a little something for you. I suggest that you spend some of it on a bath sweetie.", objectives = "Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8366] = { id = 8366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Southsea Shakedown", description = "Argh! They want the impossible from me!\n\nThe Steamwheedle Cartel wants me to teach the Southsea pirates a lesson.  The problem is that I can't be in two places at once; I need to stay here to keep the peace.\n\nOf late, the pirates have been disregarding the protection money that the cartel regularly forks over. So I'd like to temporarily deputize you to go down there and show them what for.\n\nYou'll find them at Lost Rigger Cove, which is not too far to the south.  Thanks {name}, I'll owe you one!", completion = "{name}! You are the man!!!\n\nI'm sure that the Cartel will ease up on me now that you've dealt with those Southsea scum. Let's see, what can I give you as a reward? How about a little coin and you choose from one of these for your trouble?", objectives = "Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8367] = { id = 8367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Great Honor", description = "Serving the Horde in one of the great battles against the Alliance is a source of great honor!  The few however, that have served the Horde in ALL of our active battlefronts are our truly great fighters.  We shall vanquish our opponents, not by fighting isolated skirmishes, but by waging a well-coordinated war.\n\nGo forth and crush the Alliance on every front!  For Honor!  For the Horde!", objectives = "Bring a Mark of Honor from each battleground to a Horde Warbringer in any Horde capital city or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8368] = { id = 8368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Warsong Gulch", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, {name}!  Come back to me with proof of serving the Horde in a worthy manner!", objectives = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8369] = { id = 8369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invaders of Alterac Valley", description = "Listen up, {name}.  No matter what you might have heard about the battle raging in Alterac Valley, one thing remains true: the Stormpike Expedition invaded Frostwolf Territory.  The day we allow the Alliance to invade Horde lands without a forceful response is the day I hang up my axe and live the rest of my life in shame.  Go forth and expel the invaders!", objectives = "Bring 3 Alterac Valley Marks of Honor to a Horde Warbringer outside the battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8370] = { id = 8370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquering Arathi Basin", description = "Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, {name}!", objectives = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8371] = { id = 8371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concerted Efforts", description = "We're not fighting isolated battles against the Horde anymore, <lad/lass>.\n\nVictory in one front means denying the Horde resources they'd use against us in a different battle.  By the same token, abandoning any given battle could give the advantage to our opponent somewhere else around the world.\n\nThe Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  {name}, come back to me after you've served against the Horde at all of our active battlegrounds.", objectives = "Bring a Mark of Honor from each battleground to an Alliance Brigadier General in any Alliance Capital City, Dalaran or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8372] = { id = 8372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight for Warsong Gulch", description = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, {name}!  For the Alliance!", objectives = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8373] = { id = 8373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Pine", description = "The thing I hate the most about Hallow's End are the stink bombs the Forsaken use on Southshore.  Who knew that celebrating liberation would have to involve such a smelly mess?\n\nDuring Hallow's End, use this cleaner to remove any nasty stink bombs the Horde may drop here in the village.  It uses the power of pine to fight funky smells.\n\nDo your part to keep Southshore clean, and I'll give you some Hallow's End treats I'm sure you'll enjoy.  We have a deal?", completion = "Ah, it almost smells better around here already.  Almost.\n\nThanks to you, {name}, Southshore just might make it through another Hallow's End.  Here's your treats, with my thanks!  If you run out of candy, I think there's a gnome named Katrina Shimmerstar in Ironforge who can sell you more; she's only around during Hallow's End, I believe.", objectives = "Use a Stink Bomb Cleaner to remove any Forsaken Stink Bomb that's been dropped on Southshore. Return to Sergeant Hartman in Southshore when you're done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8374] = { id = 8374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming Arathi Basin", description = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, {name}.", objectives = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8375] = { id = 8375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember Alterac Valley!", description = "Make no mistake about it, {name}.  The Horde is quite right when they say Alterac Valley is Frostwolf Territory.\n\nYou see, the Stormpike Expedition arrived as peaceful visitors to the area in search of ore and relics.  The Frostwolves reacted with the most brutal and uncivilized act of aggression the Alliance has experienced.\n\nLet us never forget the brave dwarves that perished in that cowardly unannounced attack.  Go now, {class}, do your part in the battle for Alterac Valley.  For the Alliance!", objectives = "Bring 3 Alterac Valley Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8376] = { id = 8376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armaments of War", objectives = "War comes, {name}, and with it comes untold horrors. You have done all that could be asked of you and for that you should be rewarded.\n\nShould this... this prophecy ever come to pass...\n\n<Geologist Larksbane turns pale.>\n\nThe future of us all could be at an end.\n\nThese armaments will prove invaluable to your campaign in this desert.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8377] = { id = 8377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armaments of War", objectives = "War comes, {name}, and with it comes untold horrors. You have done all that could be asked of you and for that you should be rewarded.\n\nShould this... this prophecy ever come to pass...\n\n<Geologist Larksbane turns pale.>\n\nThe future of us all could be at an end.\n\nThese armaments will prove invaluable to your campaign in this desert.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
